new:
let external_ready = self.provider_kind.is_some_and(|provider| {
    ExternalAgentProviderSelection::new(
        provider,
        &self.provider_program,
        &self.provider_args,
    )
    .is_ok()
        && self.provider_status.as_ref().is_none_or(|status| {
            status.discovered
                && status.auth != ProviderAuthStatus::NotAuthenticated
        })
});
let can_go = self.process.is_none()
    && !self.native_runtime_busy()
    && self.pending_permission.is_none()
    && match self.provider_kind {
        Some(_) => external_ready,
        None => !self.local_model_name.trim().is_empty(),
    };
